#include <iostream>
#include <functional>
#include <vector>
using namespace std;

class DinnerBell {
public:
    void listen(function<void(int)> ear) { ears.push_back(ear); }
    void ring(int what) const {
        for (auto& ear : ears) ear(what);
    }
private:
    vector<function<void(int)>> ears;
};

int main() {
    int n = 0;
    cin >> n;

    int total = 0;
    DinnerBell bell;
    bell.listen([](int x) { cout << "咪爱收到 " << x << endl; });
    bell.listen([](int x) { cout << "大肥鱼收到 " << x << endl; });
